package cn.aurange.schedule

import androidx.compose.material3.Icon
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.res.painterResource
import androidx.compose.foundation.layout.size
import androidx.compose.ui.unit.dp

// Official Lucide vectors, pinned and generated by scripts/sync-lucide-icons.ps1.
enum class Glyph(val drawable: Int) {
    Sun(R.drawable.ic_sun), Calendar(R.drawable.ic_calendar_days), CalendarCheck(R.drawable.ic_calendar_check),
    Layers(R.drawable.ic_layers), Sliders(R.drawable.ic_sliders_horizontal), ArrowUpRight(R.drawable.ic_arrow_up_right),
    ArrowRight(R.drawable.ic_arrow_right), ChevronLeft(R.drawable.ic_chevron_left), ChevronRight(R.drawable.ic_chevron_right),
    ChevronDown(R.drawable.ic_chevron_down), Check(R.drawable.ic_check), Clock(R.drawable.ic_clock), Bell(R.drawable.ic_bell),
    Refresh(R.drawable.ic_refresh_cw), Cloud(R.drawable.ic_cloud_check), Offline(R.drawable.ic_cloud_off),
    Filter(R.drawable.ic_list_filter), CircleCheck(R.drawable.ic_circle_check), Flag(R.drawable.ic_flag), Repeat(R.drawable.ic_repeat),
    Shield(R.drawable.ic_shield_check), Zap(R.drawable.ic_zap), Phone(R.drawable.ic_smartphone), Battery(R.drawable.ic_battery_full),
    Logout(R.drawable.ic_log_out), Mail(R.drawable.ic_mail), Lock(R.drawable.ic_lock_keyhole), Eye(R.drawable.ic_eye),
    EyeOff(R.drawable.ic_eye_off), Sparkles(R.drawable.ic_sparkles), Book(R.drawable.ic_book_open), Note(R.drawable.ic_square_pen), Link(R.drawable.ic_link),
    Info(R.drawable.ic_info), External(R.drawable.ic_external_link), Back(R.drawable.ic_arrow_left), Coffee(R.drawable.ic_coffee)
}

@Composable fun AppIcon(glyph: Glyph, description: String? = null, modifier: Modifier = Modifier, tint: Color = Muted) {
    Icon(painterResource(glyph.drawable), contentDescription = description, modifier = modifier.size(20.dp), tint = tint)
}
